/* Approved MY WALK overhaul. Legacy data and account sync remain in the original app. */
const MW=MyWalkV2;
let mwBibleImages=[],mwSchedule=[],mwOptional=[],mwDate=todayKey(),mwQuestion=0,mwReadingView='today',mwStudyView='home',mwPrayerAgain=false,mwPrayerDate='',mwPrayerFinished=false;
const mwSteps=['Define','Find','Look Back','Check for Symbols','Apply','Provide Clarity','Build My Position'];
const mwDescriptions=['Explain the subject in your own words.','Examine every relevant KJV passage.','Understand the setting and context.','Examine biblical comparisons in context.','Write how the truth should affect your choices and obedience.','Address misconceptions using the Scripture you studied.','Bring your findings together. Write what you believe and why.'];
const mwLegacyBackup=backupSnapshot;
backupSnapshot=function(){const snap=mwLegacyBackup();snap.data.walkV2=MW.ensure(S);return snap;};
applyTheme=function(){S.dark=true;document.documentElement.classList.add('dark');mwSceneStyle();};
ensureNotifyPermission=function(){};prayNotify=function(){};
function mwPlain(html){const d=document.createElement('div');d.innerHTML=mwClean(html);return d.textContent.trim();}
function mwClean(html){const doc=new DOMParser().parseFromString(String(html||''),'text/html');const allowed=new Set(['B','STRONG','I','EM','U','P','DIV','BR','UL','OL','LI','SPAN']);function walk(parent){for(const node of [...parent.childNodes]){if(node.nodeType!==1)continue;if(['SCRIPT','STYLE','IFRAME','OBJECT','IMG','SVG','INPUT','FORM','BUTTON'].includes(node.tagName)){node.remove();continue;}walk(node);if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);continue;}for(const a of [...node.attributes])node.removeAttribute(a.name);}}walk(doc.body);return doc.body.innerHTML;}
function mwKeyDate(date){const d=new Date(date+'T12:00:00');return Number.isNaN(d.getTime())?null:d;}
function mwDayNumber(date){const d=mwKeyDate(date);return d?dayIndexFor(d)+1:0;}
function mwPlan(date=mwDate){return mwSchedule[mwDayNumber(date)-1];}
function mwDay(date=mwDate){return MW.record(S,date,mwDayNumber(date));}
function mwRequired(plan){return [...plan.story,...plan.nonstory].map(c=>c.id);}
function mwReconcile(date=mwDate){const plan=mwPlan(date);if(!plan)return;const day=mwDay(date);if(MW.walk(day,mwRequired(plan))&&date===todayKey()){day.onTime=true;day.completedAt=day.completedAt||new Date().toISOString();}save();}
function mwHead(title,label='',action=''){return `<header class="mw-head"><div><div class="mw-label">${esc(label)}</div><h1>${esc(title)}</h1></div>${action}</header>`;}
function mwBack(action,label){return `<button class="mw-back" onclick="${action}">${ic('chevron')} ${esc(label)}</button>`;}
function mwRich(id,value,oninput){return `<div class="mw-toolbar" role="toolbar" aria-label="Writing format">${[['bold','<b>B</b>'],['italic','<i>I</i>'],['underline','<u>U</u>'],['insertUnorderedList','• List'],['insertOrderedList','1. List']].map(([cmd,label])=>`<button type="button" data-format="${cmd}" data-editor="${id}" aria-pressed="false" onmousedown="event.preventDefault()" onclick="mwFormat('${id}','${cmd}',this)" aria-label="${({bold:'Bold',italic:'Italic',underline:'Underline',insertUnorderedList:'Bulleted list',insertOrderedList:'Numbered list'})[cmd]}">${label}</button>`).join('')}</div><div id="${id}" class="mw-editor" contenteditable="true" role="textbox" aria-multiline="true" oninput="${oninput}">${mwClean(value)}</div>`;}
function mwFormat(id,cmd,button){el(id)?.focus();document.execCommand(cmd,false,null);el(id)?.dispatchEvent(new Event('input'));mwFormatState();if(button&&!matchMedia('(prefers-reduced-motion: reduce)').matches)button.animate([{transform:'scale(1)'},{transform:'scale(.9)'},{transform:'scale(1)'}],{duration:180,easing:'ease-out'});}
let mwScenes=[{image:'assets/nature/mountain.jpg',bg:'#182431',card:'#2c4052',accent:'#edbd92'},{image:'assets/nature/forest.jpg',bg:'#15251e',card:'#2b4336',accent:'#d8cc98'},{image:'assets/nature/coast.jpg',bg:'#242333',card:'#3c3b51',accent:'#d2badb'}];
function mwScene(){return mwScenes[(new Date().getDate()-1)%mwScenes.length];}
function mwSceneStyle(){document.documentElement.style.setProperty('--mw-handwriting',MW.ensure(S).handwriting==='original'?"'Rock Salt',cursive":"'MyHandwriting','Rock Salt',cursive");const theme=MW.ensure(S).theme||'system';const palettes={mountain:{bg:'#182431',card:'#2c4052',accent:'#edbd92'},forest:{bg:'#15251e',card:'#2b4336',accent:'#d8cc98'},coast:{bg:'#242333',card:'#3c3b51',accent:'#d2badb'}};const s=palettes[theme]||mwScene();for(const [name,value] of Object.entries({bg:s.bg,bg2:s.bg,card:s.card,card2:s.card,tint:s.card,accent:s.accent,gold:s.accent,blue:s.accent}))document.documentElement.style.setProperty('--'+name,value);document.getElementById('theme-color-meta')?.setAttribute('content',s.bg);}
function mwSetColor(theme){if(!['system','mountain','forest','coast'].includes(theme))return;MW.ensure(S).theme=theme;save();mwSceneStyle();document.querySelectorAll('[data-mw-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mwTheme===theme)));}
function mwYesterday(){const d=new Date();d.setDate(d.getDate()-1);return todayKey(d);}
function mwRestoreWalk(){const date=el('mw-restore-date')?.value||mwYesterday();if(!mwPlan(date)||date>=todayKey())return;document.querySelector('.modal')?.remove();modal(`<div class="mw-label">Restore WALK credit</div><h2>${esc(mwDisplayDate(date))}</h2><p>Confirm that you completed the reading, wrote a note, and prayed on this date. Your saved passages, notes, and prayer cards will stay as they are.</p><div class="mw-tools"><button class="mw-button" onclick="mwConfirmWalk('${date}')">Yes, I completed this WALK</button><button class="mw-button secondary" onclick="this.closest('.modal').remove();openSettings()">Go back</button></div>`);}
function mwConfirmWalk(date){if(!mwPlan(date)||!MW.confirmCompletion(S,date,mwDayNumber(date),todayKey()))return;save();document.querySelector('.modal')?.remove();go('home');}

function mwSetHandwriting(choice){if(!['personal','original'].includes(choice))return;MW.ensure(S).handwriting=choice;save();mwSceneStyle();}
function mwAppearanceSettings(){const selected=MW.ensure(S).theme||'system';return `<section class="mw-settings-tile"><h2>App colors</h2><p class="mw-sub">System follows the daily background’s colors. Choose a palette to keep your colors fixed.</p><div class="mw-color-grid">${[['system','System'],['mountain','Mountain · blue'],['forest','Forest · green'],['coast','Coast · plum']].map(([key,label])=>`<button class="mw-button secondary" data-mw-theme="${key}" aria-pressed="${selected===key}" onclick="mwSetColor('${key}')">${label}</button>`).join('')}</div></section><section class="mw-settings-tile"><h2>Handwriting</h2><p class="mw-sub">Choose the handwriting used for journal titles and saved entries.</p><label for="mw-handwriting-choice">Handwriting font</label><select id="mw-handwriting-choice" onchange="mwSetHandwriting(this.value)"><option value="personal" ${MW.ensure(S).handwriting!=='original'?'selected':''}>My handwriting</option><option value="original" ${MW.ensure(S).handwriting==='original'?'selected':''}>Original handwriting</option></select></section><section class="mw-settings-tile"><h2>Missed WALK credit?</h2><p class="mw-sub">If you completed reading, notes, and prayer but missed a check, confirm the date here to restore your credit and streak.</p><label for="mw-restore-date">Completed on</label><input type="date" id="mw-restore-date" value="${mwYesterday()}" max="${mwYesterday()}"><button class="mw-button" onclick="mwRestoreWalk()">Confirm completed WALK</button></section>`;}

let mwChallenges=[['Matthew 6:33','But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.'],['James 1:22','But be ye doers of the word, and not hearers only, deceiving your own selves.'],['Psalm 119:105','Thy word is a lamp unto my feet, and a light unto my path.']];
renderHome=function(){mwDate=todayKey();mwReconcile(mwDate);mwSceneStyle();const scene=mwScene(),plan=mwPlan(),day=mwDay(),stats=MW.count(S,mwSchedule,todayKey()),challenge=mwChallenges[(new Date().getDate()-1)%mwChallenges.length],mv=mwMemoryInfo(),hy=hymnOfWeek(),al=albumOfWeek(),sm=sermonsOfWeek();const read=plan&&MW.reading(day,mwRequired(plan));const subject=currentSubject(),category={doctrine:"doctrine",person:"people",study:"topics",question:"questions"}[subject.type]||"topics",sermon=mwSermonDetails(sm[0]);h(`<section class="mw-scene" style="background-image:linear-gradient(180deg,#10213125,#10213145 35%,var(--bg) 100%),url('${scene.image}')"><div class="mw-row"><div><div class="mw-home-date">${esc(mwDisplayDate(todayKey()))}</div><h1>${esc(greeting())},<br>Andrew.</h1></div><button class="mw-button secondary" onclick="openSettings()" aria-label="Settings">${ic('gear')}</button></div><div><blockquote>“${esc(challenge[1])}”</blockquote><div class="mw-ref">${esc(challenge[0])} · KJV</div></div></section><section class="mw-panel mw-walk"><div class="mw-row"><h2>Today’s WALK</h2><span class="mw-sub">${[read,MW.written(day),!!day.prayed].filter(Boolean).length} of 3</span></div><div class="mw-checks">${[['Reading','book',read,"mwOpenReading()"],['Notes','edit',MW.written(day),"mwOpenNotes()"],['Prayer','pray',day.prayed,"go('prayer')"]].map(([label,icon,done,action])=>`<button class="mw-check ${done?'done':''}" onclick="${action}">${ic(done?'check':icon)}${label}</button>`).join('')}</div><button class="mw-link" onclick="${read?'mwOpenNotes()':'mwOpenReading()'}">${read?'Continue your reading notes':'Open today’s reading'}</button>${MW.walk(day,mwRequired(plan||{story:[],nonstory:[]}))?'<p class="mw-sub" role="status">WALK complete · Your credit is saved.</p>':''}</section><section class="mw-stats"><div><strong>${stats.streak}</strong><span>Day streak</span></div><div><strong>${stats.month}</strong><span>WALKs this month</span></div><div><strong>${stats.year}</strong><span>WALKs this year</span></div></section><div class="mw-history">${Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-date.getDay()+i);const key=todayKey(date),d=MW.ensure(S).days[key],p=mwPlan(key);return `<span class="${d&&p&&MW.walk(d,mwRequired(p))?'done':''}"><b></b><small>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]}</small>${date.getDate()}</span>`;}).join('')}</div><div class="mw-home-lower">${plan?`<section class="mw-panel"><div class="mw-label">Today’s reading · Day ${plan.day}</div><h2 style="font-size:31px">${esc(plan.nonstory[0].ref)}</h2><p class="mw-sub">${esc(plan.nonstory[0].what_to_expect)}</p><div class="mw-reading-action"><button class="mw-button" onclick="mwOpenReading()">Open Devo</button></div></section>`:'<section class="mw-panel"><h2>Your scheduled journey is complete.</h2><button class="mw-button" onclick="mwOpenJournal()">Open Reading Journal</button></section>'}<section class="mw-memory"><div class="mw-label">Scripture memory</div><h2>Keep it in your heart.</h2><blockquote>“${esc(mv.text)}”</blockquote><div class="mw-ref">${esc(mv.ref)}</div><button class="mw-link" onclick="mwRenderMemory()">Practice this week’s verse</button></section><section class="mw-panel mw-home-study"><div><div class="mw-label">Current study</div><h2 style="font-size:31px">${esc(subject.title)}</h2><button class="mw-link" onclick="go('study')">Continue studying</button></div><img class="mw-home-study-art" src="assets/study/${category}-champagne.webp" alt="${category} study graphic"></section><section><div class="mw-label">Worship & listening</div><h2 style="font-size:30px">Carry it into your week.</h2><div class="mw-media"><div class="mw-art" style="background-image:url('${scene.image}')" aria-hidden="true"></div><div><div class="mw-label">Featured hymn</div><button class="mw-hymn-title" onclick="renderHymn()">${esc(hy.t)}</button><div class="mw-sub">Hymn lyrics</div></div><button class="mw-round" onclick="renderHymn()" aria-label="Open hymn">${ic('play')}</button></div><div class="mw-grid"><button class="mw-panel" onclick="mwSearchWeeklyAlbum()"><div class="mw-label">Album of the week</div><div class="mw-media-title">${esc(al?.t||'Open your album queue')}</div>${al?.a?`<div class="mw-media-credit">${esc(al.a)}</div>`:''}</button><button class="mw-panel" onclick="mwSearchWeeklySermon()"><div class="mw-label">Sermons this week</div><div class="mw-media-title">${esc(sermon.title||'Open your sermon queue')}</div>${sermon.speaker?`<div class="mw-media-credit">${esc(sermon.speaker)}</div>`:''}</button></div></section></div>`);};
function mwOpenReading(date=todayKey()){mwDate=date;mwReadingView='today';go('devo');}
function mwOpenNotes(date=todayKey()){mwDate=date;mwReadingView='notes';go('devo');}
function mwOpenJournal(){mwReadingView='journal';go('devo');}
const mwOldDevo=renderDevo;
renderDevo=function(sub){if(['hymn','albums','sermons'].includes(sub))return mwOldDevo(sub);if(mwReadingView==='notes')return mwRenderNotes();if(mwReadingView==='review')return mwReviewNotes();if(mwReadingView==='journal')return mwReadingJournal();if(mwReadingView==='optional')return mwOptionalPage();if(mwReadingView==='legacy')return mwLegacyHistory();const plan=mwPlan();if(!plan){h(mwHead('Devo','Daily time in God’s Word')+'<p>No scheduled reading for this date.</p><button class="mw-button" onclick="mwOpenJournal()">Reading Journal</button>');return;}const day=mwDay();h(`<section class="mw-reading-header" style="background-image:linear-gradient(180deg,#10213170,#10213130 40%,var(--bg) 100%),url('${mwBibleImage().url}')"><div class="mw-row"><div class="mw-label">Daily reading · ${esc(mwDate)}</div><button class="mw-button secondary" onclick="openSettings()" aria-label="Settings">${ic('gear')}</button></div><h1>Open the Word.</h1><a class="mw-sub" href="${mwBibleImage().page}" target="_blank" rel="noopener" style="font-size:10px">Photo: ${esc(mwBibleImage().credit)} / Unsplash</a><div class="mw-row"><div><strong>${plan.total}</strong><span class="mw-sub"> verses today</span></div><span class="mw-sub">Day ${plan.day} of ${mwSchedule.length}</span></div></section>${['nonstory','story'].map(track=>`<section class="mw-panel mw-reading-group"><div class="mw-row"><div><div class="mw-label">${track==='nonstory'?'Main reading · Non-story':'Story reading'}</div><h2>${track==='nonstory'?'Today’s main passages':'Today’s Bible stories'}</h2></div><span class="mw-sub">${plan[track+'_verses']} verses</span></div>${plan[track].map(c=>`<article class="mw-passage"><div class="mw-row"><h3>${esc(c.ref)}</h3><span class="mw-sub">${c.n} verses</span></div><div class="mw-label" style="margin-top:17px">What to expect</div><p>${esc(c.what_to_expect)}</p><div class="mw-row"><button class="mw-link" onclick="mwOpenChunk('${c.id}')">Open Bible app</button><button class="mw-button ${day.reads[c.id]?.done?'':'secondary'}" onclick="mwReadChunk('${c.id}')">${ic('check')} ${day.reads[c.id]?.done?'Read':'Mark read'}</button></div></article>`).join('')}</section>`).join('')}<section class="mw-journal-cover"><div class="mw-label">Your Reading Journal</div><h2 class="mw-handwritten-title">My Reading<br>Journal</h2><button class="mw-link" onclick="mwOpenJournal()">Open my journal</button><button class="mw-link" style="display:block" onclick="mwOpenNotes('${mwDate}')">${MW.questionnaire(day)?'Review today’s reflections':'Write today’s reflections'}</button></section><button class="mw-button mw-optional-button" onclick="mwReadingView='optional';renderDevo()">Optional readings</button><div class="mw-row"><button class="mw-button secondary" onclick="mwShiftDate(-1)">Previous day</button><input type="date" value="${esc(mwDate)}" max="${todayKey()}" aria-label="Reading date" onchange="mwOpenReading(this.value)"></div>`);};
function mwShiftDate(n){const d=mwKeyDate(mwDate);d.setDate(d.getDate()+n);mwOpenReading(todayKey(d));}
function mwOpenChunk(id){const c=[...mwPlan().story,...mwPlan().nonstory].find(c=>c.id===id);if(!c)return;const parts=c.ref.split(';').map(x=>x.trim());if(parts.length===1)openScripture(parts[0]);else modal('<h3>Open a passage</h3>'+parts.map(ref=>`<button class="mw-link" onclick="openScripture('${ref}')">${esc(ref)}</button>`).join('<br>'));}
function mwReadChunk(id){const d=mwDay();d.reads[id]={done:!d.reads[id]?.done,at:new Date().toISOString()};mwReconcile();renderDevo();}
function mwNotesUpdate(){const d=mwDay();d.notes[mwQuestion]={...(d.notes[mwQuestion]||{}),html:mwClean(el('mw-reading-editor').innerHTML),at:new Date().toISOString()};mwReconcile();}
function mwNotesNA(value){const d=mwDay();d.notes[mwQuestion]={...(d.notes[mwQuestion]||{}),na:value};save();}
function mwRenderNotes(){const p=mwPlan();if(!p)return renderDevo();const d=mwDay();mwQuestion=Math.max(0,Math.min(7,d.question||0));const a=d.notes[mwQuestion]||{};h(mwBack("mwReadingView='today';renderDevo()",'Daily reading')+mwHead('Reading notes',`${mwDate} · ${mwQuestion===7?'Free thoughts · Optional':'Reflection '+(mwQuestion+1)+' of 7'}`)+`<details class="mw-source"><summary>Today’s passages</summary><div class="mw-source-body">${[...p.nonstory,...p.story].map(c=>`<button class="mw-link" onclick="mwOpenChunk('${c.id}')">${esc(c.ref)}</button>`).join('<br>')}</div></details><h2 style="font-size:33px;line-height:1.2;margin:25px 0">${MW.questions[mwQuestion]}</h2>${mwRich('mw-reading-editor',a.html||'','mwNotesUpdate()')}${mwQuestion<7?`<label class="mw-na"><input type="checkbox" ${a.na?'checked':''} onchange="mwNotesNA(this.checked)">Not applicable to today’s reading</label>`:'<p class="mw-sub">Free thoughts is optional.</p>'}<div id="mw-note-error" class="mw-error" role="alert"></div><div class="mw-row"><button class="mw-button secondary" ${mwQuestion===0?'disabled':''} onclick="mwNotesMove(-1)">Back</button><button class="mw-button" onclick="mwNotesMove(1)">${mwQuestion===7?'Review answers':'Next'}</button></div><p class="mw-sub">Saved as you write.</p>`);}
function mwNotesMove(dir){mwNotesUpdate();const d=mwDay(),a=d.notes[mwQuestion]||{};if(dir>0&&mwQuestion<7&&!mwPlain(a.html)&&!a.na){el('mw-note-error').textContent='Write an answer or choose Not applicable to continue.';return;}if(dir>0&&mwQuestion===7){mwReadingView='review';return mwReviewNotes();}d.question=Math.max(0,mwQuestion+dir);save();mwRenderNotes();}
function mwReviewNotes(){const d=mwDay();h(mwBack("mwReadingView='notes';mwRenderNotes()",'Reading notes')+mwHead('Review your entry',mwDate)+MW.questions.map((q,i)=>`<section class="mw-entry"><div class="mw-label">${i===7?'Free thoughts':`Reflection ${i+1}`}</div><h2>${q}</h2><div class="mw-lined">${mwClean(d.notes[i]?.html)||esc(d.notes[i]?.na?'Not applicable':'Not yet written.')}</div><button class="mw-link" onclick="mwEditQuestion(${i})">Edit</button></section>`).join('')+`<button class="mw-button" onclick="mwCompleteNotes()">Complete reading notes</button>`);}
function mwEditQuestion(i){mwDay().question=i;mwReadingView='notes';mwRenderNotes();}
function mwCompleteNotes(){const d=mwDay();if(!MW.questionnaire(d)){const i=MW.questions.slice(0,7).findIndex((q,i)=>!mwPlain(d.notes[i]?.html)&&!d.notes[i]?.na);return mwEditQuestion(i);}d.formCompleted=new Date().toISOString();mwReconcile();mwReadingView='today';renderDevo();}
function mwReadingJournal(query=''){const v=MW.ensure(S),q=query.toLowerCase();const dates=Object.keys(v.days).filter(date=>{const d=v.days[date];return Object.keys(d.notes||{}).length&&(date+' '+Object.values(d.notes).map(a=>mwPlain(a.html)).join(' ')).toLowerCase().includes(q);}).sort().reverse();h(mwBack("mwReadingView='today';renderDevo()",'Devo')+mwHead('My Reading Journal','Your reflections, kept by date')+`<input id="mw-jsearch" class="mw-search" type="search" placeholder="Date or keyword" aria-label="Search journal" value="${esc(query)}"><details class="mw-source"><summary>Find a date</summary><div class="mw-source-body"><input type="date" max="${todayKey()}" aria-label="Entry date" onchange="mwOpenNotes(this.value)"></div></details>`+dates.map(date=>{const d=v.days[date];return `<article class="mw-entry"><div class="mw-label">${esc(fmtDate(mwKeyDate(date)))}</div><h2>Day ${d.day}</h2><div class="mw-sub">${MW.questionnaire(d)?'Complete reflections':'Partial entry'}</div><div class="mw-lined">${esc(Object.values(d.notes).map(a=>mwPlain(a.html)).find(Boolean)||'')}</div><button class="mw-link" onclick="mwDate='${date}';mwReadingView='review';mwReviewNotes()">Open entry</button></article>`;}).join('')+(!dates.length?'<p class="mw-sub">Your reflections will gather here.</p>':'')+`<button class="mw-link" onclick="mwReadingView='legacy';renderDevo()">Original reading history</button>`);el('mw-jsearch').onchange=e=>mwReadingJournal(e.target.value);}
function mwLegacyHistory(){h(mwBack("mwOpenJournal()",'Reading Journal')+mwHead('Original reading history','Preserved from your previous plan')+Object.keys(S.reads||{}).filter(i=>S.reads[i]).sort((a,b)=>a-b).map(i=>`<div class="mw-entry"><div class="mw-label">Original day ${Number(i)+1}</div><h3>${esc(D.plan[i]?.[0]?.[0]?.[0]||'Completed reading')}</h3><div class="mw-sub">${esc(JSON.stringify(D.plan[i]?.[0]||[]))}</div></div>`).join('')+`<button class="mw-link" onclick="renderNotes()">Open existing personal notes</button>`);}
function mwOptionalPage(q=''){const marks=MW.ensure(S).optional;h(mwBack("mwReadingView='today';renderDevo()",'Devo')+mwHead('Optional readings','Separate from your daily plan')+`<p class="mw-sub">${Object.values(marks).filter(x=>x?.done).length} of ${mwOptional.length} passages read</p><input class="mw-search" id="mw-osearch" type="search" aria-label="Find optional passage" placeholder="Find a book or passage" value="${esc(q)}">`+mwOptional.filter(x=>x.ref.toLowerCase().includes(q.toLowerCase())).map(x=>`<div class="mw-passage"><div class="mw-row"><button class="mw-link" onclick="openScripture('${x.ref}')">${esc(x.ref)}</button><button class="mw-button ${marks[x.id]?.done?'':'secondary'}" onclick="mwOptionalToggle('${x.id}')">${marks[x.id]?.done?'Read':'Mark read'}</button></div><span class="mw-sub">${x.verses} verses</span></div>`).join(''));el('mw-osearch').onchange=e=>mwOptionalPage(e.target.value);}
function mwOptionalToggle(id){const v=MW.ensure(S);v.optional[id]={done:!v.optional[id]?.done,at:new Date().toISOString()};save();mwOptionalPage();}
function mwStudy(){const subject=currentSubject(),key=subjectKey(subject),v=MW.ensure(S);if(!v.studies[key]){const old=S.study.position?.[key]||{};v.studies[key]={subject,steps:{},question:0};for(const [field,index] of [['def',0],['scriptures',1],['obs',2],['position',6]])if(old[field])v.studies[key].steps[index]={html:old[field],done:false};}return v.studies[key];}
function mwStudyCount(st){return Object.values(st.steps).filter(x=>x.done).length;}
const mwOldStudy=renderStudy;
renderStudy=function(sub){if(['library','topic','character','browse','notes','position','loopnext'].includes(sub||studyView))return mwOldStudy(sub);if(mwStudyView==='journal')return mwStudyJournal();if(mwStudyView==='step')return mwStudyStep();const subject=currentSubject(),st=mwStudy(),count=mwStudyCount(st),index=mwSteps.findIndex((n,i)=>!st.steps[i]?.done),category={doctrine:'doctrine',person:'people',study:'topics',question:'questions'}[subject.type]||'topics';const variant=['champagne','ice-blue','teal','plum'][Math.abs(absWeekIndex())%4];h(mwHead('Study','Search the Scriptures',`<button class="mw-button secondary" onclick="mwStudyView='journal';renderStudy()" aria-label="Study Journal">${ic('note')}</button>`)+`<section class="mw-study-hero"><div class="mw-label">Current study · ${esc(category)}</div><h1>${esc(subject.title)}</h1><img class="mw-study-object ${subject.type}" src="assets/study/${category}-${variant}.webp" alt="${esc(category)} study image"><div class="mw-study-progress"><div class="mw-row"><span class="mw-sub">Study Progress</span><span class="mw-sub">${count} of 7 steps</span></div><div class="mw-track">${mwSteps.map((n,i)=>`<span class="${st.steps[i]?.done?'done':''}"></span>`).join('')}</div><button class="mw-button" style="width:100%" onclick="mwOpenStudyStep(${index<0?6:index})">${index<0?'Review study':'Continue · '+mwSteps[index]}</button></div></section><section style="position:relative;margin:35px 0;background:linear-gradient(transparent,var(--bg) 120px)"><div class="mw-label">Your study path</div><h2 style="font-size:32px">Understand. Then respond.</h2>${mwSteps.map((n,i)=>`<button class="mw-step" onclick="mwOpenStudyStep(${i})"><span class="num">${st.steps[i]?.done?'✓':String(i+1).padStart(2,'0')}</span><span style="flex:1">${n}</span><span class="mw-sub">${st.steps[i]?.done?'Complete':''}</span></button>`).join('')}</section><div class="mw-label">Your reference shelf</div><div class="mw-grid">${[['nave',"Nave’s Topical Bible"],['webster',"Webster’s 1828"],['strongs',"Strong’s Definitions"],['mentions','KJV References']].map(([k,label])=>`<button class="mw-panel" onclick="openResource('${k}')">${esc(label)}</button>`).join('')}</div><section class="mw-journal-cover" style="background:linear-gradient(130deg,#3b484c,#223139)"><div class="mw-label">Your findings, kept together</div><h2 class="mw-handwritten-title">My Study<br>Journal</h2><button class="mw-link" onclick="mwStudyView='journal';renderStudy()">Open my journal</button></section><button class="mw-link" onclick="openLibrary()">Study Library</button>`);}
function mwOpenStudyStep(i){currentStepIdx=i;mwStudyView='step';WING='study';document.body.className='wing-study';mwStudyStep();}
function mwStudyWrite(){const st=mwStudy(),i=currentStepIdx;st.steps[i]={...(st.steps[i]||{}),html:mwClean(el('mw-study-editor').innerHTML)};st.updated=new Date().toISOString();save();}
function mwStudyNA(value){const st=mwStudy(),i=currentStepIdx;st.steps[i]={...(st.steps[i]||{}),na:value};save();}
function mwMarkStudy(){mwStudyWrite();const st=mwStudy(),s=st.steps[currentStepIdx];if(!mwPlain(s.html)&&!s.na){el('mw-study-error').textContent='Write your findings or choose Not applicable before completing this step.';return;}s.done=true;st.updated=new Date().toISOString();save();mwStudyView='home';renderStudy();}
function mwStudyStep(edit=false){const subject=currentSubject(),st=mwStudy(),i=currentStepIdx,a=st.steps[i]||{};if(a.done&&!edit){h(mwBack("mwStudyView='home';renderStudy()",'Study path')+mwHead(mwSteps[i],`${subject.title} · Step ${i+1} of 7`)+`<section class="mw-entry"><div class="mw-lined">${mwClean(a.html)||esc(a.na?'Not applicable':'Not yet written.')}</div></section><button class="mw-button" onclick="mwStudyStep(true)">Edit findings</button>`);return;}h(mwBack("mwStudyView='home';renderStudy()",'Study path')+mwHead(mwSteps[i],`${subject.title} · Step ${i+1} of 7`)+`<p class="mw-sub">${mwDescriptions[i]}</p>${[0,1,2,3].includes(i)?'<div id="mw-prepared" aria-live="polite"><p class="mw-sub">Preparing references…</p></div>':''}${i===6?`<details class="mw-source" open><summary>Your earlier findings · View & copy</summary><div class="mw-source-body">${mwSteps.slice(0,6).map((n,j)=>`<section><h3>${n}</h3><div class="mw-lined" id="mw-finding-${j}">${mwClean(st.steps[j]?.html)||esc(st.steps[j]?.na?'Not applicable':'Not yet written.')}</div><button class="mw-link" onclick="mwCopyFinding(${j})">Copy</button><span class="mw-sub" id="mw-copy-${j}"></span></section>`).join('')}</div></details>`:''}<div class="mw-label" style="margin:25px 0 12px">${i===6?'My position':'My findings'}</div>${mwRich('mw-study-editor',a.html||'','mwStudyWrite()')}<label class="mw-na"><input type="checkbox" ${a.na?'checked':''} onchange="mwStudyNA(this.checked)">Not applicable to this study</label><div class="mw-error" id="mw-study-error" role="alert"></div><button class="mw-button" onclick="mwMarkStudy()">Save & mark step complete</button>`);if(i<4)mwPrepare(subject,i).catch(e=>{const box=el('mw-prepared');if(box)box.innerHTML=`<p class="mw-error">Could not load this reference. ${esc(e.message)}</p>`;});}
async function mwCopyFinding(i){const text=el('mw-finding-'+i).textContent;try{await navigator.clipboard.writeText(text);el('mw-copy-'+i).textContent='Copied';}catch{const range=document.createRange();range.selectNodeContents(el('mw-finding-'+i));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);el('mw-copy-'+i).textContent='Text selected; use Copy.';}}
function mwSubjectTerms(subject){return [...new Set(subject.title.toLowerCase().replace(/\([^)]*\)/g,'').match(/[a-z]+/g)||[])].filter(w=>!['a','an','the','of','and','in','is','what','who','can','does','my','to','for'].includes(w));}
function mwWordMatches(term){const result=[],pattern=new RegExp('\\b'+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i');for(const [book,chs] of Object.entries(D.kjv))for(let c=0;c<chs.length;c++)for(let v=0;v<chs[c].length;v++)if(pattern.test(chs[c][v]))result.push({ref:`${book} ${c+1}:${v+1}`,text:chs[c][v]});return result;}
function mwNave(subject){return D.naves.find(x=>x.s.toLowerCase()===String(subject.ref).toLowerCase())||D.naves.find(x=>x.s.toLowerCase()===subject.title.toLowerCase());}
function mwTopicalRefs(entry){
 const refs=[];for(const sec of navesSections(entry||'')){
  if(!sec.refs)continue;let book=null,chapter=null,last=0;
  const tokens=new RegExp('\\b'+CODE_RE+'\\b|\\d+(?::\\d+)?(?:[-–]\\d+(?::\\d+)?)?','g');let m;
  while((m=tokens.exec(sec.refs))){const gap=sec.refs.slice(last,m.index),token=m[0];last=tokens.lastIndex;
   if(BOOKMAP[token]){book=BOOKMAP[token];chapter=null;continue;}
   if(!book||!/^[\s;,]*(?:(?:with|and|cf\.?|to)[\s;,]*)?$/i.test(gap)){book=null;continue;}
   const parts=token.split(/[-–]/),a=parts[0].split(':').map(Number),b=parts[1]?.split(':').map(Number);
   const verseList=a.length===1&&chapter&&gap.includes(',');
   let c1=a[0],v1=1,c2=a[0],v2=null;
   if(a.length===2){chapter=c1;v1=a[1];c2=b?.length===2?b[0]:c1;v2=b?b[b.length-1]:v1;}
   else if(verseList){c1=c2=chapter;v1=a[0];v2=b?b[0]:v1;}
   else {chapter=null;c2=b?b[0]:c1;}
   for(let c=c1;c<=c2;c++){const verses=D.kjv[book]?.[c-1];if(!verses)continue;const first=c===c1?v1:1,end=c===c2&&v2!==null?v2:verses.length;for(let v=first;v<=end;v++)if(verses[v-1])refs.push({ref:`${book} ${c}:${v}`,text:verses[v-1]});}
  }
 }return [...new Map(refs.map(r=>[r.ref,r])).values()];
}
function mwPassages(refs){return refs.map(r=>`<details class="mw-source"><summary>${esc(r.ref)}</summary><div class="mw-source-body">${esc(r.text)}<br><button class="mw-link" onclick="openScripture('${r.ref}')">Open Bible app</button></div></details>`).join('');}
async function mwPrepare(subject,i){const key=subjectKey(subject),terms=mwSubjectTerms(subject),nave=mwNave(subject);let html='';if(i===0){const dictionaries=await Promise.all(terms.map(async word=>{const data=await getWebster(word[0]);return {word,defs:data[word]||[]};}));html=`<details class="mw-source" open><summary>Webster’s 1828 Dictionary</summary><div class="mw-source-body">${dictionaries.map(({word,defs})=>`<h3>${esc(word)}</h3>${defs.length?defs.map(d=>`<div class="mw-label">${esc(d[0])}</div><p>${esc(d[1])}</p>`).join(''):'<p>No exact dictionary entry.</p>'}`).join('')}</div></details><details class="mw-source"><summary>Nave’s Topical Bible</summary><div class="mw-source-body">${nave?navesAccordion(nave.e):'No exact topical entry for this subject.'}</div></details>`;const strong=await getStrongs(),usage=await mwGetStrongUsage(),ids=[...new Set(terms.flatMap(t=>strong.i[t]||[]))].filter(id=>strong.e[id]);html+=`<details class="mw-source"><summary>Strong’s Definitions · ${ids.length} indexed entries</summary><div class="mw-source-body"><p class="mw-sub">Entries indexed by this subject’s English words. Expand each entry to see its original-language word and sourced KJV usage.</p>${ids.map(id=>{const e=strong.e[id];return `<h3>${id} · ${esc(e.x||e.l)}</h3><p>${esc(e.d)}</p><details><summary>KJV translation words</summary><p>${esc(e.k)}</p></details><details ontoggle="mwStrongUsage(this,'${id}')"><summary>Passages using ${id} · ${(usage[id]||[]).length} verses</summary><div class="mw-usage-results"></div></details>`;}).join('')||'No indexed entries.'}</div></details>`;for(const t of terms)html+=`<details class="mw-source"><summary>Passages containing “${esc(t)}”</summary><div class="mw-source-body">${mwPassages(mwWordMatches(t))}</div></details>`;}else if(i===1){for(const t of terms){const matches=mwWordMatches(t);html+=`<div class="mw-label">Exact word · ${esc(t)} · ${matches.length} verses</div>${mwPassages(matches)}`;}if(nave){const refs=mwTopicalRefs(nave.e);html+=`<details class="mw-source"><summary>Topical references · ${refs.length} expanded verses</summary><div class="mw-source-body">${navesAccordion(nave.e)}${mwPassages(refs)}</div></details>`;}}else if(i===2){html=`<div class="mw-sub">Read these references in their surrounding chapter. Historical claims are not generated without an attributed source.</div>${nave?`<details class="mw-source"><summary>Source context · Nave’s</summary><div class="mw-source-body">${navesAccordion(nave.e)}</div></details>`:'<p>No subject-specific background source is bundled. Record your findings below.</p>'}${mwPassages(mwTopicalRefs(nave?.e).slice(0,30))}`;}else{const sections=navesSections(nave?.e||'').filter(x=>/figur|symbol|type|simil|compar|metaphor/i.test(x.label));html=sections.length?sections.map(s=>`<details class="mw-source"><summary>${esc(s.label)}</summary><div class="mw-source-body">${linkifyNaves(s.refs)}</div></details>`).join(''):'<p class="mw-sub">No explicit symbolism section is indexed for this subject. Do not force a connection; Not applicable is available.</p>';}if(subjectKey(currentSubject())===key&&currentStepIdx===i&&el('mw-prepared'))el('mw-prepared').innerHTML=html;}
function mwStudyJournal(query='',filter='all'){const studies=Object.entries(MW.ensure(S).studies).filter(([key,st])=>{const n=mwStudyCount(st);return (filter==='all'||(filter==='complete'?n===7:n<7))&&(st.subject.title+' '+Object.values(st.steps).map(x=>mwPlain(x.html)).join(' ')).toLowerCase().includes(query.toLowerCase());});h(mwBack("mwStudyView='home';renderStudy()",'Study')+mwHead('My Study Journal','What I believe. And why.')+`<input id="mw-sjsearch" class="mw-search" type="search" value="${esc(query)}" placeholder="Search subjects, findings, or Scripture" aria-label="Search Study Journal"><div class="mw-tools">${[['all','All'],['progress','In progress'],['complete','Completed']].map(([f,label])=>`<button class="mw-button ${filter===f?'':'secondary'}" onclick="mwStudyJournal('${query.replace(/'/g,'')}', '${f}')">${label}</button>`).join('')}</div>`+studies.map(([key,st])=>`<section class="mw-entry"><div class="mw-label">${esc(st.subject.type)}</div><h2>${esc(st.subject.title)}</h2><div class="mw-sub">${mwStudyCount(st)} of 7 steps</div><button class="mw-link" onclick="mwResumeStudy('${encodeURIComponent(key)}')">Open study</button></section>`).join('')+`<button class="mw-link" onclick="setStudyView('library')">Original studies & full library</button>`);el('mw-sjsearch').onchange=e=>mwStudyJournal(e.target.value,filter);}
function mwResumeStudy(key){const st=MW.ensure(S).studies[decodeURIComponent(key)];if(st){libSubject=st.subject;mwStudyView='home';renderStudy();}}
const mwOldPrayer=renderPrayer,mwOldFlash=prayerFlashInner;
renderPrayer=function(sub){if(sub)prayerView=sub;h(`<section class="mw-water" style="background-image:linear-gradient(180deg,#18243120,transparent 40%,var(--bg)),url('assets/prayer-water.jpg')"><div class="mw-label">${esc(fmtDate(new Date()))}</div><h1>Bring it<br>before Him.</h1><blockquote>“Be still, and know that I am God.”</blockquote><div class="mw-ref">Psalm 46:10 · KJV</div></section><div class="mw-tabs">${[['today','Today'],['overview','Overview'],['tree','List'],['log','Answered']].map(([key,label])=>`<button class="${prayerView===key?'on':''}" onclick="setPrayerView('${key}')">${label}</button>`).join('')}</div><div id="pv"></div>`);({today:renderPray,overview:renderOverview,tree:renderManage,log:renderLog}[prayerView]||renderPray)();};
function mwPrayerSnapshot(){const pd=prayerDue(),d=mwDay(todayKey());d.prayerDue=pd.items.map(x=>x.it.id);const done=S.prayerChecks[todayKey()]||[];if(pd.items.length&&pd.items.every(c=>done.includes(c.it.id))){d.prayed=true;d.prayedAt=d.prayedAt||new Date().toISOString();mwReconcile(todayKey());}return pd;}
function mwPrayerMarkup(){const pd=mwPrayerSnapshot(),done=S.prayerChecks[todayKey()]||[],remaining=pd.items.filter(c=>!done.includes(c.it.id));if(mwPrayerDate!==todayKey()){mwPrayerDate=todayKey();mwPrayerAgain=false;mwPrayerFinished=false;flashPos=MW.ensure(S).prayerCursor?.[mwPrayerDate]??Math.max(0,pd.items.findIndex(c=>!done.includes(c.it.id)));}if(!pd.items.length)return '<section class="mw-panel"><h2>Your prayer list</h2><p class="mw-sub">Add people and requests, then choose when to pray for them.</p><button class="mw-button" onclick="setPrayerView(\'tree\')">Build your list</button></section>';if(!remaining.length&&!mwPrayerAgain)return `<section class="mw-summary"><div class="mw-label">Today’s prayer complete</div><h1>Amen.</h1><p class="mw-sub">You brought each of today’s requests before God.</p><blockquote>“The LORD is nigh unto all them that call upon him, to all that call upon him in truth.”</blockquote><div class="mw-ref">Psalm 145:18 · KJV</div><button class="mw-button" onclick="mwPrayerAgain=true;flashPos=0;prayRerender()">Pray through again</button></section>`;flashPos=Math.min(Math.max(0,flashPos),pd.items.length-1);const c=pd.items[flashPos],v=verseForItem();let inner=mwOldFlash(c,v,pd.items.length);for(const request of c.it.requests)if(request.html)inner=inner.replace(esc(request.text)+'</span>',mwClean(request.html)+'</span>');const timerAt=inner.indexOf('<div class="ptimer"');if(timerAt>=0)inner=inner.slice(0,timerAt);const track=`<div class="mw-track">${pd.items.map(x=>`<span class="${done.includes(x.it.id)?'done':''}"></span>`).join('')}</div>`;return `<div class="mw-row"><span class="mw-label">Today’s prayer cards</span><span class="mw-sub">${done.filter(id=>pd.items.some(x=>x.it.id===id)).length} of ${pd.items.length} prayed</span></div>${track}<article data-card-position="${flashPos}" class="flash ${done.includes(c.it.id)?'prayed':''}" id="${prayFocusOpen?'prayflashF':'prayflash'}" onclick="prayCardTap(event)">${inner}</article><div class="mw-row" style="margin:17px 0"><button class="mw-button secondary" onclick="mwPrayerMove(-1,false)" aria-label="Previous card">${ic('chevron','mw-previous')}</button><span class="mw-sub">${flashPos+1} of ${pd.items.length} · Swipe when prayed</span><button class="mw-button secondary" onclick="mwPrayerMove(1,true)" aria-label="Mark prayed and next">${ic('chevron')}</button></div>${!prayFocusOpen?`<details class="mw-prayer-tools"><summary>${ic('gear')}<span>Prayer tools<span class="mw-tools-caption" style="display:block">Timer · Answers · Skip</span></span></summary>${mwPrayerTools(c)}</details>`:''}${mwTimerDock()}`;}
function mwPrayerTools(c){return `<div class="mw-tools"><button class="mw-button secondary" onclick="mwPrayerMove(1,false)">Skip for now</button><button class="mw-button secondary" onclick="prayAnswer('${c.hd.id}','${c.it.id}')">Record an answer</button></div>${mwTimerRunning()?'':`<div class="ptimer" id="ptimer">${prayTimerHTML(c)}</div>`}`;}
renderPray=function(){el('pv').innerHTML=mwPrayerMarkup();mountPraySwipe('prayflash');};
function mwPrayerMove(dir,mark){if(mwCardSliding)return;mwSlideDirection=dir;const pd=prayerDue();if(!pd.items.length)return;const c=pd.items[flashPos];if(mark){const done=S.prayerChecks[todayKey()]=S.prayerChecks[todayKey()]||[];if(!done.includes(c.it.id))done.push(c.it.id);}mwPrayerSnapshot();if(dir>0&&flashPos===pd.items.length-1&&mark){mwPrayerAgain=false;}else flashPos=(flashPos+dir+pd.items.length)%pd.items.length;const v=MW.ensure(S);if(!v.prayerCursor)v.prayerCursor={};v.prayerCursor[todayKey()]=flashPos;save();prayRerender();}
prayAdvance=function(dir){mwPrayerMove(dir,dir>0);};praySkip=function(){mwPrayerMove(1,false);};
mountPraySwipe=function(id){const card=el(id);if(!card)return;let x=0,y=0;card.style.touchAction='pan-y';card.addEventListener('pointerdown',e=>{x=e.clientX;y=e.clientY;prayDragMoved=false;});card.addEventListener('pointermove',e=>{if(Math.abs(e.clientX-x)>15)prayDragMoved=true;});card.addEventListener('pointerup',e=>{const dx=e.clientX-x,dy=e.clientY-y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.3){prayDragMoved=true;mwPrayerMove(dx<0?1:-1,dx<0);}setTimeout(()=>prayDragMoved=false,150);});};
openPrayerFocus=function(){prayFocusOpen=true;renderPrayerFocus();const node=el('prayfocus');if(node?.requestFullscreen)node.requestFullscreen().catch(()=>{});};
closePrayerFocus=function(){prayFocusOpen=false;stopPrayTimer(true);stopEachTimer(true);el('prayfocus')?.remove();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});renderPray();};
renderPrayerFocus=function(){document.querySelectorAll('#pv .mw-timer-dock').forEach(node=>node.remove());const pd=prayerDue();if(!pd.items.length)return closePrayerFocus();let node=el('prayfocus');if(!node){node=document.createElement('div');node.id='prayfocus';node.className='prayfocus';document.body.append(node);}const c=pd.items[Math.min(flashPos,pd.items.length-1)],done=S.prayerChecks[todayKey()]||[];node.innerHTML=`<div class="mw-focusbar"><div class="mw-track">${pd.items.map(x=>`<span class="${done.includes(x.it.id)?'done':''}"></span>`).join('')}</div><details class="mw-focussettings"><summary aria-label="Prayer settings">${ic('gear')}</summary><div class="mw-menu"><button class="mw-button secondary" onclick="closePrayerFocus()">Exit full screen</button>${mwPrayerTools(c)}</div></details></div>${mwPrayerMarkup()}`;mountPraySwipe('prayflashF');};
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&prayFocusOpen&&el('prayfocus'))closePrayerFocus();});
renderOverview=function(){const pd=mwPrayerSnapshot(),done=S.prayerChecks[todayKey()]||[],n=pd.items.filter(c=>done.includes(c.it.id)).length;el('pv').innerHTML=`<section class="mw-panel"><div class="mw-label">Today at a glance</div><h2 style="font-size:34px">A place for every burden.</h2><div class="mw-stats"><div><strong>${n}</strong><span>Prayed today</span></div><div><strong>${pd.items.length-n}</strong><span>Remaining</span></div><div><strong>${pd.items.length}</strong><span>Scheduled cards</span></div></div><button class="mw-button" onclick="setPrayerView('today')">Continue praying</button></section><h2 style="font-size:29px">Your prayer categories</h2><div class="mw-grid">${S.prayer.headings.map(hd=>`<button class="mw-panel" onclick="setPrayerView('tree')"><div class="mw-label">${hd.items.length} cards</div><h3>${esc(hd.name)}</h3><span class="mw-sub">${hd.items.reduce((n,it)=>n+it.requests.length,0)} requests</span></button>`).join('')}</div><button class="mw-link" onclick="setPrayerView('log')">Answered prayers · ${S.testimony.length} praise reports</button>`;};
const mwOldSettings=openSettings;
openSettings=function(){modal(`<div class="mw-settings"><header class="mw-settings-head"><div><div class="mw-label">MY WALK</div><h1>Settings</h1></div><button class="mw-settings-close" aria-label="Close settings" onclick="this.closest('.modal').remove()">×</button></header>${mwAppearanceSettings()}<section class="mw-settings-tile"><div class="mw-row">${ic('gear')}<h2>Account & Sync</h2></div><p class="mw-sub">Continue on your phone, iPad, and laptop.</p><button class="mw-button" onclick="this.closest('.modal').remove();window.mywalkCloud.panel()">Open account</button></section><section class="mw-journal-cover"><div class="mw-label">A thought worth keeping</div><h2>Standalone notes</h2><button class="mw-link" onclick="this.closest('.modal').remove();mwStandalone()">Open my notes</button></section><div class="mw-label">Keep your work safe</div><div class="mw-grid" style="margin:18px 0"><button class="mw-panel" onclick="exportBackupFile()">${ic('note')} Download backup</button><button class="mw-panel" onclick="importBackupFile()">Restore backup</button></div><button class="mw-link" onclick="this.closest('.modal').remove();mwAdvancedSettings()">Advanced backup settings</button><details class="mw-source"><summary>Photo credits</summary><div class="mw-source-body">${mwBibleImages.map(image=>`<a href="${image.page}" target="_blank" rel="noopener">${esc(image.credit)} / Unsplash</a>`).join('<br>')}<br>Nature scenes and Study objects were created for MY WALK.</div></details></div>`);};
function mwAdvancedSettings(){mwOldSettings();const toggle=el('dark-toggle');if(toggle){const set=toggle.closest('.sset');const label=set?.previousElementSibling;set?.remove();if(label?.textContent==='Appearance')label.remove();}}
function mwStandalone(edit=false){const v=MW.ensure(S);const head=mwBack("go('home');openSettings()",'Settings')+mwHead('Standalone notes','A thought worth keeping');if(v.notes.general&&!edit){h(head+`<section class="mw-entry"><div class="mw-lined">${mwClean(v.notes.general)}</div></section><button class="mw-button" onclick="mwStandalone(true)">Edit note</button>`);return;}h(head+mwRich('mw-standalone',v.notes.general||'',"MW.ensure(S).notes.general=mwClean(this.innerHTML);save()")+`<button class="mw-button" style="margin-top:18px" onclick="mwStandalone()">Done writing</button>`);}

function mwScriptureText(text){return String(text||'').replace(/\{[^}]*\}/g,'').replace(/\s+/g,' ').trim();}
function mwMemoryInfo(){const v=MW.ensure(S),d=new Date(),monday=new Date(d.getFullYear(),d.getMonth(),d.getDate()-((d.getDay()+6)%7)),key=todayKey(monday);const existing=v.memory[key];if(!existing||existing.selectionVersion!==2){
 const subject=currentSubject(),refs=mwTopicalRefs(mwNave(subject)?.e),refSet=new Set(refs.map(x=>x.ref));
 const curated=['Psalms 119:11','Proverbs 3:5','Proverbs 3:6','Joshua 1:8','Psalms 1:2','Psalms 19:14','Psalms 56:3','Isaiah 26:3','Micah 6:8','Matthew 6:33','John 15:5','Romans 12:2','Romans 8:28','1 Corinthians 10:13','2 Corinthians 5:17','Galatians 2:20','Galatians 5:22','Galatians 5:23','Ephesians 4:32','Philippians 4:6','Philippians 4:7','Philippians 4:13','Colossians 3:16','2 Timothy 2:15','2 Timothy 3:16','Hebrews 11:6','Hebrews 12:2','James 1:22','James 4:8','1 Peter 5:7','1 John 1:9'];
 const relevant=curated.filter(ref=>refSet.has(ref)),pool=relevant.length?relevant:curated,ref=pool[Math.abs(absWeekIndex())%pool.length],p=parseRef(ref),text=mwScriptureText(D.kjv[p.book][p.ch-1][p.vStart-1]);
 v.memory[key]={ref,text,subject:relevant.length?subject.title:'Scripture for daily living',hidden:existing?.ref===ref?existing.hidden||{}:{},week:key,selectionVersion:2};save();
 }else existing.text=mwScriptureText(existing.text);return v.memory[key];}

let mwMemorySelected=null;
function mwRenderMemory(){const m=mwMemorySelected||mwMemoryInfo();h(mwBack("mwMemorySelected=null;go('home')",'Home')+mwHead('Scripture memory',m.subject||'Memorized verse')+`<section class="mw-memory"><blockquote>${esc(m.text)}</blockquote><div class="mw-ref">${esc(m.ref)}</div></section><div class="mw-tools">${m.text.split(/\s+/).map((w,i)=>`<button class="mem-w" onclick="mwMemoryHide(${i})">${m.hidden?.[i]?'_____':esc(w)}</button>`).join('')}</div><div class="mw-tools"><button class="mw-button secondary" onclick="mwMemoryMore()">Hide more words</button><button class="mw-button secondary" onclick="mwMemoryReveal()">Reveal all</button><button class="mw-button" onclick="mwMemoryMemorized()">Mark memorized</button></div><details class="mw-source"><summary>Memorized verses · ${S.memArchive.length}</summary><div class="mw-source-body">${S.memArchive.map((x,i)=>`<button class="mw-link" onclick="mwMemoryReview(${i})">${esc(x.ref)}</button>`).join('<br>')}</div></details>`);}
function mwMemoryHide(i){const m=mwMemorySelected||mwMemoryInfo();m.hidden=m.hidden||{};m.hidden[i]=!m.hidden[i];save();mwRenderMemory();}
function mwMemoryMore(){const m=mwMemorySelected||mwMemoryInfo(),n=m.text.split(/\s+/).length;m.hidden=m.hidden||{};const available=Array.from({length:n},(_,i)=>i).filter(i=>!m.hidden[i]);for(let j=0;j<Math.min(3,available.length);j++){const i=available.splice(Math.floor(Math.random()*available.length),1)[0];m.hidden[i]=true;}save();mwRenderMemory();}
function mwMemoryReveal(){(mwMemorySelected||mwMemoryInfo()).hidden={};save();mwRenderMemory();}
function mwMemoryMemorized(){const m=mwMemorySelected||mwMemoryInfo();if(!S.memArchive.some(x=>x.ref===m.ref))S.memArchive.push({ref:m.ref,text:m.text,topic:m.subject||'',date:todayKey()});save();mwRenderMemory();}
function mwMemoryReview(i){mwMemorySelected={...S.memArchive[i],text:mwScriptureText(S.memArchive[i].text),hidden:{}};mwRenderMemory();}
const mwOriginalBoot=boot;
boot=async function(){[mwSchedule,mwOptional,mwBibleImages,mwScenes,mwChallenges]=await Promise.all([j('data/schedule.json'),j('data/optional-readings.json'),j('data/bible-images.json'),j('data/nature-scenes.json'),j('data/home-scripture.json').then(rows=>rows.map(r=>[r.ref,r.text]))]);if(!localStorage.getItem('mywalk_before_v2')&&localStorage.getItem(LS))localStorage.setItem('mywalk_before_v2',localStorage.getItem(LS));MW.ensure(S);await mwOriginalBoot();};
// Keep prayer replay separate from today's earned completion.
prayReset=function(itemId){const pd=prayerDue();flashPos=Math.max(0,pd.items.findIndex(c=>c.it.id===itemId));mwPrayerAgain=true;prayRerender();};
// Preserve original rich text but never treat whitespace-only markup as a note.
const mwOriginalH=h;
h=function(html){mwOriginalH(html);document.querySelectorAll('#app button,.sheet button').forEach(button=>{const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT);while(walker.nextNode())walker.currentNode.textContent=walker.currentNode.textContent.replace(/[→↗←]/g,'');});};
async function mwGetStrongUsage(){if(!D.strongUsage){const data=await j('data/strongs-usage.json');D.strongUsage=data.entries;D.strongUsageBooks=data.books;}return D.strongUsage;}
async function mwStrongUsage(details,id){if(!details.open||details.dataset.loaded)return;const usage=await mwGetStrongUsage();const refs=(usage[id]||[]).map(n=>{const b=D.strongUsageBooks[Math.floor(n/1000000)],c=Math.floor(n%1000000/1000),v=n%1000;return {ref:`${b} ${c}:${v}`,text:D.kjv[b]?.[c-1]?.[v-1]||''};});details.querySelector('.mw-usage-results').innerHTML=mwPassages(refs);details.dataset.loaded='true';}
const mwPreviousGo=go,mwPreviousNavDesc=navDesc,mwPreviousNavApply=navApply;
go=function(w,sub){mwSceneStyle();if(w==='study'&&WING!=='study'){studyView='home';mwStudyView='home';}mwPreviousGo(w,sub);};
navDesc=function(){if(WING==='devo')return {w:'devo',v2:true,view:mwReadingView,date:mwDate};if(WING==='study'&&['home','subject'].includes(studyView))return {w:'study',v2:true,view:mwStudyView,step:currentStepIdx,subject:libSubject};return mwPreviousNavDesc();};
navApply=function(d){if(!d.v2)return mwPreviousNavApply(d);navSuppress=true;try{if(d.w==='devo'){mwDate=d.date||todayKey();mwReadingView=d.view||'today';mwPreviousGo('devo');}else if(d.w==='study'){studyView='home';mwStudyView=d.view||'home';currentStepIdx=d.step||0;libSubject=d.subject||null;mwPreviousGo('study');}}finally{navSuppress=false;}};
// All matches are retained, but long reference lists render in small batches.
const mwPassageSets=new Map();let mwPassageSerial=0;
mwPassages=function(refs){const id='refs-'+(++mwPassageSerial);mwPassageSets.set(id,{refs,index:Math.min(100,refs.length)});return `<div class="mw-reference-list" data-list="${id}">${refs.slice(0,100).map(mwPassageRow).join('')}${refs.length>100?`<button class="mw-button secondary" onclick="mwMoreReferences(this,'${id}')">Show next references · ${refs.length-100} remaining</button>`:''}</div>`;};
function mwPassageRow(r){return `<details class="mw-source" ontoggle="mwExpandPassage(this,'${encodeURIComponent(r.ref)}')"><summary>${esc(r.ref)}</summary><div class="mw-source-body"></div></details>`;}
function mwExpandPassage(node,encoded){if(!node.open||node.dataset.loaded)return;const ref=decodeURIComponent(encoded),p=parseRef(ref),text=p?D.kjv[p.book]?.[p.ch-1]?.[(p.vStart||1)-1]:'';node.querySelector('.mw-source-body').innerHTML=`${esc(text||'Passage text is unavailable.')}<br><button class="mw-link" onclick="openScripture('${ref}')">Open Bible app</button>`;node.dataset.loaded='true';}
function mwMoreReferences(button,id){const set=mwPassageSets.get(id);if(!set)return;const chunk=set.refs.slice(set.index,set.index+100);button.insertAdjacentHTML('beforebegin',chunk.map(mwPassageRow).join(''));set.index+=chunk.length;if(set.index>=set.refs.length)button.remove();else button.textContent=`Show next references · ${set.refs.length-set.index} remaining`;}

function mwBibleImage(){return mwBibleImages[(new Date().getDate()-1)%mwBibleImages.length]||{url:"",credit:"",page:"https://unsplash.com"};}
const mwPreviousSceneStyle=mwSceneStyle;
mwSceneStyle=function(){mwPreviousSceneStyle();const scene=mwScene();if(scene){const image=new Image();image.src=scene.image;image.onerror=()=>{const el=document.querySelector('.mw-scene');if(el)el.style.backgroundImage='linear-gradient(160deg,var(--card),var(--bg))';};}};

// Store both plain text for legacy consumers and formatted text for the new editors.
openItem=function(hi,ii){const hd=S.prayer.headings[hi],it=hd.items[ii];const m=modal(`<div class="mw-label">${esc(hd.name)}</div><h2>${esc(it.name)}</h2><p class="mw-sub">${schedLabel(it.sched)}</p><button class="mw-link" id="mw-edit-card">Edit card & schedule</button>${it.requests.map((r,i)=>`<section class="mw-entry"><div>${r.html?mwClean(r.html):esc(r.text)}</div><div class="mw-tools"><button class="mw-button secondary" data-answer="${i}">Answered</button><button class="mw-link" data-remove="${i}">Remove request</button></div></section>`).join('')}<h3>New request</h3>${mwRich('mw-new-request','','')}<button class="mw-button" id="mw-add-request">Add request</button>`);
 m.querySelector('#mw-edit-card').onclick=()=>{m.remove();editItem(hi,ii);};
 m.querySelector('#mw-add-request').onclick=()=>{const html=mwClean(m.querySelector('#mw-new-request').innerHTML),text=mwPlain(html);if(!text)return;it.requests.push({id:pid(),text,html,added:todayKey()});save();m.remove();openItem(hi,ii);};
 m.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{it.requests.splice(+b.dataset.remove,1);save();m.remove();openItem(hi,ii);});
 m.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ri=+b.dataset.answer,r=it.requests[ri];m.remove();mwPraise(hd,it,r,()=>{it.requests.splice(ri,1);openItem(hi,ii);});});
};
function mwPraise(hd,it,request,after){const m=modal(`<div class="mw-label">Answered prayer</div><h2>${esc(it.name)}</h2><p>${esc(request?.text||it.name)}</p><h3>How did God answer?</h3>${mwRich('mw-praise','','')}<p class="mw-sub">Your praise report is optional.</p><button class="mw-button" id="mw-save-praise">Record answer</button>`);m.querySelector('#mw-save-praise').onclick=()=>{const noteHtml=mwClean(m.querySelector('#mw-praise').innerHTML);S.testimony.unshift({date:todayKey(),heading:hd.name,item:it.name,text:request?.text||it.name,note:mwPlain(noteHtml),noteHtml,cat:hd.name});m.remove();if(after)after();save();};}
prayAnswer=function(hid,iid){const hd=S.prayer.headings.find(h=>h.id===hid),it=hd?.items.find(x=>x.id===iid);if(!it)return;stopPrayTimer(true);stopEachTimer(true);mwPraise(hd,it,null,()=>{const done=S.prayerChecks[todayKey()]=S.prayerChecks[todayKey()]||[];if(!done.includes(iid))done.push(iid);mwPrayerSnapshot();prayRerender();});};
renderLog=function(){const now=new Date(),items=S.testimony.filter(t=>logFilter==='all'||(logFilter==='month'?t.date.slice(0,7)===todayKey(now).slice(0,7):t.date.slice(0,4)===String(now.getFullYear())));el('pv').innerHTML=`<h2>Remember His goodness.</h2><div class="mw-tabs">${[['all','All answers'],['month','This month'],['year','This year']].map(([f,label])=>`<button class="${logFilter===f?'on':''}" onclick="logFilter='${f}';renderLog()">${label}</button>`).join('')}</div>${items.map(t=>`<section class="mw-entry"><div class="mw-label">${esc(t.date)} · ${esc(t.cat||t.heading||'Prayer')}</div><h3>${esc(t.item)}</h3><p class="mw-journal-text">${esc(t.text||'')}</p><div class="mw-journal-text">${t.noteHtml?mwClean(t.noteHtml):esc(t.note||'')}</div></section>`).join('')||'<p class="mw-sub">Your answered prayers will gather here.</p>'}<button class="mw-button" onclick="setPrayerView('today')">Return to prayer</button>`;};

function mwDisplayDate(key){const date=mwKeyDate(key);return date.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});}
function mwSermonDetails(sermon){if(!sermon)return {title:'',speaker:''};const title=sermon.t||'',parts=title.split(/\s+[—–]\s+/);return {title:parts.length>1?parts.slice(0,-1).join(' — '):title,speaker:sermon.speaker||sermon.preacher||(parts.length>1?parts[parts.length-1]:'')};}
const mwReviewH=h;
h=function(html){mwReviewH(html);const walker=document.createTreeWalker(el('app'),NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(!node.parentElement.closest('[contenteditable],script,style,textarea'))node.textContent=node.textContent.replace(/\b\d{4}-\d{2}-\d{2}\b/g,mwDisplayDate);}document.querySelectorAll('.mw-journal-cover h2,.mw-head h1').forEach(title=>{if(/^(My )?(Reading|Study)\s+Journal$/.test(title.textContent))title.classList.add('mw-handwritten-title');});};

function mwSearchWeeklyAlbum(){const album=albumOfWeek();if(album)location.href=appleMusicSearch(album.t,album.a);else go('devo','albums');}
function mwSearchWeeklySermon(){const sermon=mwSermonDetails(sermonsOfWeek()[0]);if(sermon.title)location.href=appleMusicSearch(sermon.title,sermon.speaker);else go('devo','sermons');}
renderHymn=function(){const hy=hymnOfWeek();h(mwBack("go('home')",'Home')+mwHead('Hymn of the week',`Week ${hy.w}`)+`<section class="mw-panel"><h2>${esc(hy.t)}</h2><p class="mw-sub">${esc(hy.a||'')}</p><a class="mw-button" href="${appleMusicSearch(hy.t)}">Search on Apple Music</a></section><section class="lyrics mw-hymn-lyrics">${hymnVerses(hy)}</section>`);};

function mwTimerRunning(){return !!(listTimerId||prayTimerId||eachTimerId);}
function mwTimerDock(){if(!mwTimerRunning())return '';const end=listTimerId?listSegEnd:eachTimerId?eachEnd:prayTimerEnd,duration=listTimerId?listPerCard:eachTimerId?eachSegDur:prayTimerDur,left=Math.max(0,Math.ceil((end-Date.now())/1000)),percent=duration?Math.max(0,Math.min(100,100*(1-left/duration))):0;return `<div class="mw-timer-dock" aria-label="Prayer timer"><div class="mw-timer-controls"><span class="mw-sub">${listTimerId?'Time for this card':eachTimerId?'Time for this request':'Prayer timer'}</span><span id="pt-count">${fmtClock(left)}</span><button class="mw-link" onclick="mwStopTimer()" aria-label="Stop prayer timer"><span class="mw-stop-icon" aria-hidden="true"></span></button></div><div class="mw-timer-track"><span id="pt-bar" style="width:${percent}%"></span></div></div>`;}
function mwStopTimer(){stopListTimer(true);stopPrayTimer(true);stopEachTimer(true);prayRerender();}

function mwFormatState(){const selection=window.getSelection(),node=selection?.anchorNode,element=node?.nodeType===1?node:node?.parentElement,editor=element?.closest('.mw-editor');if(!editor)return;document.querySelectorAll('.mw-toolbar button[data-editor]').forEach(button=>{if(button.dataset.editor!==editor.id)return;let active=false;try{active=document.queryCommandState(button.dataset.format);}catch{}button.setAttribute('aria-pressed',String(active));});}
document.addEventListener('selectionchange',mwFormatState);
document.addEventListener('input',event=>{if(event.target.closest?.('.mw-editor'))mwFormatState();});

let mwCardSliding=false,mwSlideDirection=0;
const mwImmediatePrayerRender=prayRerender;
prayRerender=function(){const oldCard=el(prayFocusOpen?'prayflashF':'prayflash'),previous=Number(oldCard?.dataset.cardPosition);if(mwCardSliding)return;if(!oldCard||previous===flashPos||matchMedia('(prefers-reduced-motion: reduce)').matches){mwSlideDirection=0;mwImmediatePrayerRender();return;}
 const direction=mwSlideDirection||(flashPos>previous?1:-1);mwSlideDirection=0;mwCardSliding=true;
 const width=oldCard.getBoundingClientRect().width;
 const outgoing=oldCard.animate([{transform:'translateX(0)',opacity:1},{transform:`translateX(${-direction*width}px)`,opacity:.2}],{duration:160,easing:'ease-in',fill:'forwards'});
 outgoing.finished.catch(()=>{}).then(()=>{mwImmediatePrayerRender();const nextCard=el(prayFocusOpen?'prayflashF':'prayflash');if(!nextCard){mwCardSliding=false;return;}return nextCard.animate([{transform:`translateX(${direction*width}px)`,opacity:.2},{transform:'translateX(0)',opacity:1}],{duration:210,easing:'cubic-bezier(.2,.75,.25,1)'}).finished.catch(()=>{}).then(()=>{mwCardSliding=false;});}).finally(()=>{mwCardSliding=false;});
};
